package dev.cosmerearcanists.power;
import com.mojang.authlib.GameProfile;
import dev.cosmerearcanists.*;
import dev.cosmerearcanists.mobs.*;
import dev.cosmerearcanists.koloss.*;
import dev.cosmerearcanists.hemalurgy.*;
import dev.cosmerearcanists.equipment.EquipmentContent;
import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.npc.Villager;
import net.minecraft.world.item.*;
import net.neoforged.neoforge.common.util.FakePlayer;
import net.neoforged.neoforge.event.entity.living.*;
import net.neoforged.neoforge.gametest.*;
@GameTestHolder(CosmereArcanists.MOD_ID)
@PrefixGameTestTemplate(false)
public final class NaturalMobGameTests {
    private static long count(LivingEntity e){return PowerAttributes.keys().stream().filter(k->{var a=e.getAttribute(PowerAttributes.holder(k));return a!=null&&a.getBaseValue()>0;}).count();}
    private static Villager villager(GameTestHelper h){return EntityType.VILLAGER.create(h.getLevel());}
    private static FakePlayer caster(GameTestHelper h){var p=new FakePlayer(h.getLevel(),new GameProfile(UUID.randomUUID(),"KolossController"));p.setPos(h.absolutePos(new BlockPos(2,20,2)).getCenter());for(String m:List.of("zinc","brass")){PowerAttributes.set(p,"a:"+m,1);PowerData.state(p,"a:"+m,2);PowerData.reserve(p,m,100);}return p;}
    @GameTest(template="empty") public static void kolossRequiresStrongControlForBothEmotionalMetals(GameTestHelper h){var p=caster(h);var k=KolossContent.KOLOSS.get().create(h.getLevel());k.setPos(p.position());try{h.assertTrue(SpiritualIntegrity.get(k)==1,"No invented spiritual damage is required for natural koloss control");for(String power:List.of("a:zinc","a:brass")){DominationService.remove(k);EmotionService.clear(k);PowerAttributes.set(p,power,1);h.assertTrue(EmotionService.apply(p,k,power,Emotion.COMPLIANCE)&&DominationService.owner(k)==null,"Ordinary emotional strength cannot seize koloss");PowerAttributes.set(p,power,4);h.assertTrue(EmotionService.apply(p,k,power,Emotion.COMPLIANCE)&&DominationService.owner(k)==p,"Threshold strength can control koloss with either metal");h.assertTrue(DominationService.remaining(k)>0&&!DominationService.permits(k,p),"Existing minion timer and owner protections apply");}var ordinary=villager(h);ordinary.setPos(p.position());EmotionService.apply(p,ordinary,"a:zinc",Emotion.COMPLIANCE);h.assertTrue(DominationService.owner(ordinary)==null,"Intact ordinary humanoids still require spiritual damage");}finally{DominationService.remove(k);EmotionService.clear(k);}h.succeed();}
    @GameTest(template="empty") public static void kolossShieldingAndConfigCanPreventAndReleaseControl(GameTestHelper h){var p=caster(h);var k=KolossContent.KOLOSS.get().create(h.getLevel());k.setPos(p.position());boolean old=KolossConfig.EMOTIONAL_CONTROL.get();try{PowerAttributes.set(p,"a:zinc",10);k.setItemSlot(EquipmentSlot.HEAD,new ItemStack(EquipmentContent.SPIKES.get("aluminum").get()));h.assertTrue(!EmotionService.apply(p,k,"a:zinc",Emotion.COMPLIANCE)&&DominationService.owner(k)==null,"Aluminum headwear still blocks control");k.setItemSlot(EquipmentSlot.HEAD,ItemStack.EMPTY);h.assertTrue(EmotionService.apply(p,k,"a:zinc",Emotion.COMPLIANCE)&&DominationService.owner(k)==p,"Unshielded strong control works");KolossConfig.EMOTIONAL_CONTROL.set(false);DominationService.tick();h.assertTrue(DominationService.owner(k)==null,"Disabling natural koloss control releases an intact target");}finally{KolossConfig.EMOTIONAL_CONTROL.set(old);DominationService.remove(k);EmotionService.clear(k);}h.succeed();}
    @GameTest(template="empty") public static void birthRollPersistsAndDoesNotRestoreRemovedPowers(GameTestHelper h){int cooldown=NaturalMobConfig.CHUNK_COOLDOWN_SECONDS.get(),odds=NaturalMobConfig.ONE_IN.get();boolean sets=NaturalMobConfig.SETS.get(),both=NaturalMobConfig.BOTH.get();try{NaturalMobConfig.CHUNK_COOLDOWN_SECONDS.set(0);NaturalMobConfig.ONE_IN.set(1);NaturalMobConfig.SETS.set(false);NaturalMobConfig.BOTH.set(false);var mob=villager(h);NaturalMobPowers.initialize(mob);h.assertTrue(NaturalMobPowers.checked(mob)&&count(mob)==1,"Eligible vanilla humanoids have real personal power attributes");UUID identity=NaturalMobPowers.identity(mob);var tag=new CompoundTag();mob.saveWithoutId(tag);var copy=villager(h);copy.load(tag);h.assertTrue(count(copy)==1&&identity.equals(NaturalMobPowers.identity(copy)),"Saved attributes and roll marker survive reload");for(String key:PowerAttributes.keys())copy.getAttribute(PowerAttributes.holder(key)).setBaseValue(0);NaturalMobPowers.initialize(copy);h.assertTrue(count(copy)==0,"Reloading/rechecking cannot replace a stolen or administratively removed power");}finally{NaturalMobConfig.CHUNK_COOLDOWN_SECONDS.set(cooldown);NaturalMobConfig.ONE_IN.set(odds);NaturalMobConfig.SETS.set(sets);NaturalMobConfig.BOTH.set(both);}h.succeed();}
    @GameTest(template="empty") public static void fullSetsAndExclusionsRespectSpawnSettings(GameTestHelper h){int cooldown=NaturalMobConfig.CHUNK_COOLDOWN_SECONDS.get(),odds=NaturalMobConfig.ONE_IN.get(),setOdds=NaturalMobConfig.SET_ONE_IN.get();boolean sets=NaturalMobConfig.SETS.get(),both=NaturalMobConfig.BOTH.get(),enabled=NaturalMobConfig.ENABLED.get();try{NaturalMobConfig.CHUNK_COOLDOWN_SECONDS.set(0);NaturalMobConfig.ONE_IN.set(1);NaturalMobConfig.SET_ONE_IN.set(1);NaturalMobConfig.SETS.set(true);NaturalMobConfig.BOTH.set(false);var mob=villager(h);NaturalMobPowers.initialize(mob);h.assertTrue(count(mob)==16,"Full set grants all16standard powers in one art");var koloss=KolossContent.KOLOSS.get().create(h.getLevel());NaturalMobPowers.initialize(koloss);h.assertTrue(count(koloss)==16,"Koloss use the same tagged humanoid policy and attribute support");var cow=EntityType.COW.create(h.getLevel());var zombie=EntityType.ZOMBIE.create(h.getLevel());NaturalMobPowers.initialize(cow);NaturalMobPowers.initialize(zombie);h.assertTrue(count(cow)==0&&count(zombie)==0,"Animals and undead receive no birth roll");NaturalMobConfig.ENABLED.set(false);var unpowered=villager(h);NaturalMobPowers.initialize(unpowered);NaturalMobConfig.ENABLED.set(true);NaturalMobPowers.initialize(unpowered);h.assertTrue(count(unpowered)==0,"Disabled-spawn result is not rerolled after config changes");}finally{NaturalMobConfig.CHUNK_COOLDOWN_SECONDS.set(cooldown);NaturalMobConfig.ONE_IN.set(odds);NaturalMobConfig.SET_ONE_IN.set(setOdds);NaturalMobConfig.SETS.set(sets);NaturalMobConfig.BOTH.set(both);NaturalMobConfig.ENABLED.set(enabled);}h.succeed();}
    @GameTest(template="empty") public static void conversionPreservesSourceIdentityAndCannotReroll(GameTestHelper h){int cooldown=NaturalMobConfig.CHUNK_COOLDOWN_SECONDS.get(),odds=NaturalMobConfig.ONE_IN.get();try{NaturalMobConfig.CHUNK_COOLDOWN_SECONDS.set(0);NaturalMobConfig.ONE_IN.set(1);var original=villager(h);NaturalMobPowers.initialize(original);var converted=EntityType.ZOMBIE_VILLAGER.create(h.getLevel());new NaturalMobPowers().converted(new LivingConversionEvent.Post(original,converted));h.assertTrue(count(converted)==count(original)&&NaturalMobPowers.identity(original).equals(NaturalMobPowers.identity(converted)),"Conversion copies actual powers and original source Identity");for(String key:PowerAttributes.keys())converted.getAttribute(PowerAttributes.holder(key)).setBaseValue(0);var cured=villager(h);new NaturalMobPowers().converted(new LivingConversionEvent.Post(converted,cured));NaturalMobPowers.initialize(cured);h.assertTrue(count(cured)==0&&NaturalMobPowers.checked(cured),"Conversion/cure loop cannot restore removed powers");}finally{NaturalMobConfig.CHUNK_COOLDOWN_SECONDS.set(cooldown);NaturalMobConfig.ONE_IN.set(odds);}h.succeed();}
    @GameTest(template="empty") public static void naturallyAssignedPowerCanActuallyBeStolen(GameTestHelper h){int cooldown=NaturalMobConfig.CHUNK_COOLDOWN_SECONDS.get(),odds=NaturalMobConfig.ONE_IN.get(),setOdds=NaturalMobConfig.SET_ONE_IN.get();boolean sets=NaturalMobConfig.SETS.get(),both=NaturalMobConfig.BOTH.get();try{NaturalMobConfig.CHUNK_COOLDOWN_SECONDS.set(0);NaturalMobConfig.ONE_IN.set(1);NaturalMobConfig.SET_ONE_IN.set(1);NaturalMobConfig.SETS.set(true);NaturalMobConfig.BOTH.set(false);var donor=villager(h);NaturalMobPowers.initialize(donor);String metal=donor.getAttribute(PowerAttributes.holder("a:steel")).getBaseValue()>0?"steel":"pewter";var source=HemalurgySources.select(donor,metal);h.assertTrue(source!=null&&!source.trait(),"A natural power is eligible for the corresponding power-stealing spike");var p=caster(h);var spike=new ItemStack(EquipmentContent.SPIKES.get(metal).get());p.setItemInHand(InteractionHand.MAIN_HAND,spike);donor.setHealth(0);HemalurgyService.capture(new LivingDeathEvent(donor,p.damageSources().playerAttack(p)));HemalurgyService.flush();var charge=HemalurgicSpikes.contents(spike);h.assertTrue(charge!=null&&charge.power().equals(source.power())&&donor.getAttribute(PowerAttributes.holder(source.power())).getBaseValue()==0,"Lethal theft transfers natural power into a real charged spike and removes it from donor");h.assertTrue(charge.sources().getFirst().identity().equals(NaturalMobPowers.identity(donor)),"Spike retains natural source Identity");}finally{NaturalMobConfig.CHUNK_COOLDOWN_SECONDS.set(cooldown);NaturalMobConfig.ONE_IN.set(odds);NaturalMobConfig.SET_ONE_IN.set(setOdds);NaturalMobConfig.SETS.set(sets);NaturalMobConfig.BOTH.set(both);HemalurgyService.flush();}h.succeed();}
    @GameTest(template="empty") public static void nativeEggInitializationActuallyRollsPowers(GameTestHelper h){
        int cooldown=NaturalMobConfig.CHUNK_COOLDOWN_SECONDS.get(),odds=NaturalMobConfig.ONE_IN.get();boolean sets=NaturalMobConfig.SETS.get(),both=NaturalMobConfig.BOTH.get();Villager mob=null;
        try{NaturalMobConfig.CHUNK_COOLDOWN_SECONDS.set(0);NaturalMobConfig.ONE_IN.set(1);NaturalMobConfig.SETS.set(false);NaturalMobConfig.BOTH.set(false);mob=EntityType.VILLAGER.spawn(h.getLevel(),h.absolutePos(new BlockPos(2,20,2)),MobSpawnType.SPAWN_EGG);h.assertTrue(mob!=null&&NaturalMobPowers.checked(mob)&&count(mob)==1,"Native finalize-spawn event assigns exactly one power with forced single-art settings");}
        finally{NaturalMobConfig.CHUNK_COOLDOWN_SECONDS.set(cooldown);NaturalMobConfig.ONE_IN.set(odds);NaturalMobConfig.SETS.set(sets);NaturalMobConfig.BOTH.set(both);if(mob!=null)mob.discard();}h.succeed();
    }

}
